// mixed models: half the flow is in the microtask queue
function load(id: string): Promise<Order | null> {
  return api.get(id)
    .then(r => r.ok ? mapOrder(r) : null)
    .catch(() => null);
}

// one model
async function load(id: string): Promise<Order | null> {
  try { const r = await api.get(id); return r.ok ? mapOrder(r) : null; }
  catch { return null; }
}
